<script>
import {tick} from 'svelte';
import {rectangle, point, paint} from './core.js';
let canvas, image=null, boxes=[], pending=null, start=null, width=0, height=0;
let error='', status='No image loaded', preview='', approved=false, busy=false, generation=0;
let x=0,y=0,w=100,h=40,actualSize=false;
function invalidate(){if(preview)URL.revokeObjectURL(preview);preview='';approved=false;}
function draw(){if(canvas&&image)paint(canvas.getContext('2d'),image,pending?[...boxes,pending]:boxes);}
function changed(){invalidate();draw();}
async function show(img, label){image=img;width=img.naturalWidth||img.width;height=img.naturalHeight||img.height;boxes=[];pending=null;start=null;invalidate();status=label;error='';await tick();draw();}
async function load(event){
 const file=event.target.files[0]; if(!file)return;
 const token=++generation;busy=true;invalidate();error='';
 try{
  if(!['image/png','image/jpeg'].includes(file.type))throw new Error('Choose a PNG or JPEG image. SVG, GIF and PDF are not supported.');
  if(file.size>16*1024*1024)throw new Error('Choose an image smaller than 16 MiB.');
  const url=URL.createObjectURL(file);let img=new Image();
  try{img.src=url;await img.decode();}finally{URL.revokeObjectURL(url);}
  if(img.naturalWidth*img.naturalHeight>12_000_000||Math.max(img.naturalWidth,img.naturalHeight)>8192)throw new Error('Image is too large. Use at most 12 megapixels and 8192 pixels per side.');
  if(token!==generation)return;await show(img,'Image ready. Mark every sensitive area.');
 }catch(e){if(token===generation){error=e.message;image=null;boxes=[];width=0;height=0;status='No image loaded';}}
 finally{if(token===generation)busy=false;event.target.value='';}
}
async function sample(){++generation;busy=false;const c=document.createElement('canvas');c.width=1000;c.height=600;const ctx=c.getContext('2d');ctx.fillStyle='#f4f2e9';ctx.fillRect(0,0,1000,600);ctx.fillStyle='#152b30';ctx.font='bold 35px sans-serif';ctx.fillText('FICTIONAL SUPPORT TICKET',55,85);ctx.font='24px sans-serif';ctx.fillText('Customer: Sample Person',55,165);ctx.fillText('Email: example@example.test',55,220);ctx.fillText('Reference: DEMO-1234-5678',55,275);ctx.fillStyle='#53666a';ctx.font='21px sans-serif';ctx.fillText('Keep the issue visible. Cover details that are not needed.',55,400);ctx.fillText('This demo contains no real customer data.',55,450);await show(c,'Fictional demo ready. Try covering the email and reference.');}
function down(event){if(!image||busy)return;invalidate();start=point(event.clientX,event.clientY,canvas.getBoundingClientRect(),width,height);canvas.setPointerCapture(event.pointerId);}
function move(event){if(!start)return;const end=point(event.clientX,event.clientY,canvas.getBoundingClientRect(),width,height);pending=rectangle(start,end,width,height);draw();}
function up(event){if(!start)return;const end=point(event.clientX,event.clientY,canvas.getBoundingClientRect(),width,height);if(Math.abs(end.x-start.x)>=2&&Math.abs(end.y-start.y)>=2){boxes=[...boxes,rectangle(start,end,width,height)];status=`${boxes.length} solid cover${boxes.length===1?'':'s'} added.`;}start=null;pending=null;changed();}
function cancel(){start=null;pending=null;draw();}
function add(){error='';try{const values=[x,y,w,h].map(Number);if(!values.every(Number.isFinite)||values[2]<=0||values[3]<=0)throw new Error('Enter valid coordinates and a positive width and height.');boxes=[...boxes,rectangle({x:values[0],y:values[1]},{x:values[0]+values[2],y:values[1]+values[3]},width,height)];changed();status=`${boxes.length} solid covers added.`;}catch(e){error=e.message;}}
async function review(){error='';if(!image||!boxes.length)return;const token=generation;busy=true;try{const c=document.createElement('canvas');c.width=width;c.height=height;paint(c.getContext('2d'),image,boxes);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw new Error('Could not encode the PNG. Try a smaller image.');if(token!==generation)return;invalidate();preview=URL.createObjectURL(blob);status='Review the actual flattened PNG below before downloading.';}catch(e){error=e.message;}finally{if(token===generation)busy=false;}}
function reset(){++generation;image=null;boxes=[];start=null;pending=null;width=0;height=0;busy=false;invalidate();error='';status='Image cleared from this page. Previously downloaded files are not deleted.';}
</script>

<svelte:head><title>SolidFrame | Local screenshot covers</title></svelte:head>
<div class="shell">
<header><div class="brand"><svg width="42" height="42" viewBox="0 0 48 48" aria-label="N inside an image frame" role="img"><rect width="48" height="48" rx="12" fill="#bcf269"/><path d="M9 12h30v24H9z" fill="none" stroke="#16352b" stroke-width="2"/><path d="M16 32V17h4l8 10V17h4v15h-4l-8-10v10z" fill="#16352b"/></svg><span>SolidFrame<small>SCREENSHOT COVERS / SVELTE</small></span></div><span class="local">LOCAL PROCESSING · NO UPLOADS</span></header>
<main><section class="intro"><p class="eyebrow">KEEP THE CONTEXT. COVER THE DETAILS.</p><h1>A solid cover.<br/>A flattened copy.</h1><p>Mark private details with opaque boxes, then inspect the exact PNG you will download. No blur. No account. No automatic detection.</p></section>
<div class="workspace"><section class="editor" aria-label="Image editor"><div class="toolbar"><label class="filebutton">Open image<input aria-label="Open PNG or JPEG" type="file" accept="image/png,image/jpeg" onchange={load} disabled={busy}/></label><button onclick={sample} disabled={busy}>Try a fictional demo</button><button class="quiet" onclick={reset}>Clear image</button></div>
{#if image}<div class="imageinfo">{width} × {height} pixels <span>{boxes.length} solid cover{boxes.length===1?'':'s'}</span><button class="zoom" onclick={()=>actualSize=!actualSize}>{actualSize?'Fit image':'Actual pixel size'}</button></div><div class="canvaswrap"><canvas style:width={actualSize?`${width}px`:'100%'} bind:this={canvas} {width} {height} onpointerdown={down} onpointermove={move} onpointerup={up} onpointercancel={cancel} aria-label="Image preview. Drag to cover an area, or use the coordinate fields beside it."></canvas></div>{:else}<div class="empty"><div class="frameicon">N</div><h2>Start with a screenshot</h2><p>PNG or JPEG · up to 16 MiB / 12 megapixels<br/>Your original file stays unchanged.</p></div>{/if}
<p class="status" role="status">{status}</p>{#if error}<p class="error" role="alert">{error}</p>{/if}
</section>
<aside><h2>01 / Cover</h2><p>Drag across a detail. Add a generous margin. Each box expands by 2 source pixels at its edges.</p><fieldset disabled={!image||busy}><legend>Or add a box by coordinates</legend><div class="coords"><label>X<input type="number" bind:value={x}/></label><label>Y<input type="number" bind:value={y}/></label><label>Width<input type="number" min="1" bind:value={w}/></label><label>Height<input type="number" min="1" bind:value={h}/></label></div><button onclick={add}>Add solid cover</button></fieldset><button class="quiet" disabled={!boxes.length||busy} onclick={()=>{boxes=boxes.slice(0,-1);changed();}}>Undo last cover</button><hr/><h2>02 / Inspect the copy</h2><p>Look for missed names, corners, tabs, avatars and reflected details. A cover only removes the pixels inside it.</p><button class="primary" disabled={!image||!boxes.length||busy} onclick={review}>{busy?'Working…':'Build review PNG'}</button><p class="fine">Nothing is saved in browser storage. The original stays in this tab until you clear it or close the page. Do not share the original by mistake.</p></aside></div>
{#if preview}<section class="review"><div><p class="eyebrow">ACTUAL EXPORT PREVIEW</p><h2>Check every edge before sharing.</h2><p>This is the flattened PNG, not an editable overlay. The exported name is always generic.</p></div><button class="quiet" onclick={()=>actualSize=!actualSize}>{actualSize?'Fit image':'Actual pixel size'}</button><div class="exportwrap"><img style:width={actualSize?`${width}px`:'100%'} style:max-width={actualSize?'none':'100%'} src={preview} alt="Actual flattened export for manual inspection"/></div><label class="approve"><input type="checkbox" bind:checked={approved}/> I inspected this copy and covered every detail I intend to remove.</label>{#if approved}<a class="download" href={preview} download="solidframe-covered.png">Download inspected PNG</a>{:else}<button disabled>Inspect and confirm to download</button>{/if}</section>{/if}
<section class="limits"><h2>Deliberately manual.</h2><p>No OCR, no face detection and no promise that every sensitive detail is covered. Other people may infer information from visible context or box size. Covering an image does not revoke leaked credentials or delete an original. PNG/JPEG only; no PDFs, animations or layered files. If your browser cannot decode or export the image, nothing is downloaded.</p></section></main><footer>Built by Nelli · MIT licensed · No analytics, remote fonts or external runtime requests.</footer>
</div>

<style>
:global(*){box-sizing:border-box}:global(body){margin:0;background:#112a2a;color:#e8eee7;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.55}:global(button),.filebutton,.download{font:inherit;border:1px solid #557068;background:#253f3b;color:#f6faf1;border-radius:9px;padding:10px 16px;cursor:pointer;text-decoration:none;display:inline-block;font-weight:600}:global(button:disabled){opacity:.4;cursor:not-allowed}:global(button:focus-visible),:global(input:focus-visible),.filebutton:focus-within,.download:focus-visible{outline:3px solid #bcf269;outline-offset:3px}.shell{max-width:1400px;margin:auto;padding:30px 42px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #3b5450;padding-bottom:25px}.brand{display:flex;align-items:center;gap:12px;font-size:22px;font-weight:700}.brand small{display:block;letter-spacing:1.7px;font-size:9px;color:#a2b9ae;font-weight:400}.local{font-size:10px;letter-spacing:1.4px;color:#bcf269}.intro{display:grid;grid-template-columns:1fr 1fr;gap:10px 70px;padding:42px 0 32px}.eyebrow{font-size:10px;letter-spacing:2px;color:#bcf269;font-weight:bold;grid-column:1/-1}h1{font-size:clamp(35px,4vw,57px);line-height:1.05;letter-spacing:-2px;margin:0}.intro>p:last-child{max-width:440px;color:#b3c5bb;align-self:end;font-size:17px}h2{font-size:18px;margin:0 0 12px}p{margin:0 0 15px}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:22px}.editor{background:#edf0e7;color:#19302a;border-radius:16px;overflow:hidden;align-self:start}.toolbar{padding:15px;display:flex;flex-wrap:wrap;gap:8px;border-bottom:1px solid #d0d7c8}.toolbar button,.toolbar .filebutton{font-size:12px;padding:9px 12px}.filebutton{background:#193d30;position:relative;overflow:hidden}.filebutton input{position:absolute;inset:0;opacity:0;width:100%;cursor:pointer}.quiet{background:transparent;color:inherit;border-color:#789084}.toolbar .quiet{color:#344a40}.imageinfo{padding:12px 18px;font-size:12px;color:#526456;display:flex;justify-content:space-between}.canvaswrap{padding:0 16px 16px;overflow:auto;max-height:75vh}.exportwrap{overflow:auto;max-height:75vh}.zoom{font-size:10px!important;padding:3px 8px!important;margin-left:8px}.imageinfo{flex-wrap:wrap;align-items:center;gap:6px}canvas{display:block;width:100%;height:auto;background:repeating-conic-gradient(#deded8 0% 25%,#f7f7f1 0% 50%) 0/16px 16px;touch-action:none;cursor:crosshair}.empty{min-height:350px;text-align:center;display:flex;align-items:center;justify-content:center;flex-direction:column;padding:25px}.empty p{font-size:13px;color:#68776a}.frameicon{font-size:45px;line-height:1;border:3px solid #8a9f80;border-radius:10px;width:80px;padding:14px;margin-bottom:25px;font-weight:bold;color:#4f6d45}.status{padding:13px 18px;margin:0;font-size:12px;background:#e1e8d8}.error{padding:15px;color:#9d2b24;font-weight:bold}aside{background:#1c3733;padding:25px;border:1px solid #3c5950;border-radius:16px}aside p{font-size:13px;color:#bdcec3}fieldset{padding:0;border:0;margin:20px 0 12px}legend{font-size:12px;color:#c1d1c5;margin-bottom:12px}.coords{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px}.coords label{font-size:11px;color:#b6c6b9}.coords input{display:block;width:100%;background:#102923;color:white;border:1px solid #597364;border-radius:5px;padding:8px;font:inherit}fieldset button,aside>button{width:100%;font-size:13px}hr{border:0;border-top:1px solid #3f5b4e;margin:25px 0}.primary,.download{background:#bcf269!important;border-color:#bcf269!important;color:#16352b!important}.fine{font-size:11px!important;margin-top:16px!important}.review{margin-top:26px;background:#e9eee1;color:#19302a;border-radius:16px;padding:25px}.review .eyebrow{color:#4f6f2d}.review img{display:block;max-width:100%;height:auto;margin:20px auto;background:#ddd;border:1px solid #83987b}.review .approve{display:flex;gap:10px;font-size:14px;align-items:flex-start;margin:20px 0}.approve input{margin-top:5px;accent-color:#2a633b}.review button{color:#19302a}.limits{max-width:850px;padding:35px 0 15px}.limits p{color:#a7beb0;font-size:12px}footer{border-top:1px solid #3b5450;padding-top:20px;color:#99afa2;font-size:10px}@media(max-width:800px){.shell{padding:20px}.local{display:none}.intro{grid-template-columns:1fr;padding-top:28px;gap:20px}.intro>p:last-child{font-size:15px}.workspace{grid-template-columns:1fr}h1{letter-spacing:-1px}.empty{min-height:260px}aside{padding:20px}.review{padding:18px}}
</style>
